package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.linear.*;
import org.apache.commons.math3.distribution.TDistribution;

/** One-way independent-cluster inference for a marginal observed-data SEM. */
public final class ClusterSem {
    private ClusterSem(){}
    public record Options(FimlSem.Options estimator,boolean smallSampleCorrection,int bootstrapReplicates,long seed){
        public Options{Objects.requireNonNull(estimator);if(bootstrapReplicates!=0&&(bootstrapReplicates<20||bootstrapReplicates>2000))throw new IllegalArgumentException("Choose no bootstrap or 20–2,000 whole-cluster replicates.");}
        public static Options defaults(){return new Options(FimlSem.Options.defaults(),true,0,42);}
    }
    public record Term(String parameter,double estimate,double clusterStandardError,double referenceDegreesOfFreedom,double statistic,double pValue,double lower,double upper,Double bootstrapLower,Double bootstrapUpper){}
    public record Replicate(int index,int sampledRows,boolean usable,double[] estimates,String issue){public Replicate{estimates=estimates.clone();}@Override public double[] estimates(){return estimates.clone();}}
    public record Fit(FimlSem.Fit point,Options options,int suppliedClusters,int informativeClusters,List<Integer> informativeClusterSizes,double correctionFactor,double[][] clusterCovariance,int clusterScoreRank,List<Term> terms,int attemptedBootstrap,int successfulBootstrap,List<Replicate> bootstrap,List<String> warnings){
        public Fit{informativeClusterSizes=List.copyOf(informativeClusterSizes);clusterCovariance=Matrices.copy(clusterCovariance);terms=List.copyOf(terms);bootstrap=List.copyOf(bootstrap);warnings=List.copyOf(warnings);}@Override public double[][] clusterCovariance(){return Matrices.copy(clusterCovariance);}
    }
    static LinkedHashMap<String,List<Integer>> groups(double[][] data,List<String> ids){
        if(ids==null||ids.size()!=data.length)throw new IllegalArgumentException("Provide exactly one cluster ID per original input row.");LinkedHashMap<String,List<Integer>> groups=new LinkedHashMap<>();for(int i=0;i<ids.size();i++){String id=ids.get(i);if(id==null||id.isBlank()||id.length()>500)throw new IllegalArgumentException("Cluster IDs must be nonblank labels of at most 500 characters.");groups.computeIfAbsent(id,k->new ArrayList<>()).add(i);}if(groups.size()<3||groups.size()>10000)throw new IllegalArgumentException("Provide 3–10,000 independent clusters.");return groups;
    }
    public static Fit fit(double[][] data,List<String> ids,SemModel.Model model,Options options,java.util.function.IntConsumer progress){
        Objects.requireNonNull(options);var groups=groups(data,ids);var point=FimlSem.fit(data,model,options.estimator());var likelihood=new SemObservedLikelihood(data,model);int q=model.parameters().size(),n=point.observations();double[] theta=new double[q];for(int j=0;j<q;j++)theta[j]=point.estimates()[j]/model.parameters().get(j).scale();double[][] scores=likelihood.caseScores(theta);List<double[]> summed=new ArrayList<>();List<Integer> sizes=new ArrayList<>();
        for(var rows:groups.values()){double[] sum=new double[q];int informative=0;for(int index:rows){if(Arrays.stream(data[index]).anyMatch(Double::isFinite))informative++;for(int j=0;j<q;j++)sum[j]+=scores[index][j]/model.parameters().get(j).scale();}if(informative>0){summed.add(sum);sizes.add(informative);}}
        int g=summed.size();if(g<3)throw new IllegalArgumentException("At least three clusters must contain observed values.");if(options.smallSampleCorrection()&&n<=q)throw new IllegalArgumentException("CR1 correction requires more informative rows than free parameters.");double correction=options.smallSampleCorrection()?(double)g/(g-1)*(n-1)/(n-q):1;double[][] covariance=new double[q][q];for(var row:covariance)Arrays.fill(row,Double.NaN);int rank=0;
        if(q>0&&point.converged()&&point.locallyIdentified()&&!point.boundary()){
            double[][] meat=new double[q][q];for(var score:summed)for(int i=0;i<q;i++)for(int j=0;j<q;j++)meat[i][j]+=score[i]*score[j];RealMatrix m=new Array2DRowRealMatrix(meat);double[] scales=new double[q];for(int j=0;j<q;j++)scales[j]=Math.sqrt(Math.max(0,meat[j][j]));double[][] correlation=new double[q][q];for(int i=0;i<q;i++)for(int j=0;j<q;j++)correlation[i][j]=scales[i]>0&&scales[j]>0?meat[i][j]/scales[i]/scales[j]:0;double[] singular=new SingularValueDecomposition(new Array2DRowRealMatrix(correlation)).getSingularValues();for(double value:singular)if(value>1e-9)rank++;RealMatrix bread=new Array2DRowRealMatrix(point.parameterCovariance());covariance=bread.multiply(m).multiply(bread).scalarMultiply(correction).getData();
        }
        List<Replicate> replicates=new ArrayList<>();int successful=0;Random rng=new Random(options.seed());List<List<Integer>> units=new ArrayList<>(groups.values());
        for(int b=0;b<options.bootstrapReplicates();b++){
            Matrices.interrupted();List<Integer> selected=new ArrayList<>();for(int j=0;j<units.size();j++)selected.addAll(units.get(rng.nextInt(units.size())));double[] estimate=new double[q];Arrays.fill(estimate,Double.NaN);boolean usable=false;String issue="";
            try{if(selected.size()>20000)throw new IllegalArgumentException("Resampled cluster sizes exceed the 20,000-row estimator cap.");double[][] sample=new double[selected.size()][];for(int j=0;j<sample.length;j++)sample[j]=data[selected.get(j)].clone();var fitted=FimlSem.fit(sample,model,options.estimator());usable=fitted.converged()&&fitted.locallyIdentified()&&!fitted.boundary();if(usable){estimate=fitted.estimates();successful++;}else issue="Nonconverged, unidentified or boundary replicate";}catch(java.util.concurrent.CancellationException cancelled){throw cancelled;}catch(RuntimeException invalid){issue=Objects.toString(invalid.getMessage(),invalid.getClass().getSimpleName());}replicates.add(new Replicate(b+1,selected.size(),usable,estimate,issue));if(progress!=null)progress.accept(b+1);
        }
        List<Term> terms=new ArrayList<>();TDistribution t=new TDistribution(g-1);double critical=t.inverseCumulativeProbability((1+options.estimator().confidence())/2),tail=(1-options.estimator().confidence())/2;for(int j=0;j<q;j++){var parameter=model.parameters().get(j);double estimate=point.estimates()[j],se=Math.sqrt(covariance[j][j]);boolean testable=parameter.locations().stream().noneMatch(l->l.kind()==SemModel.Kind.COVARIANCE);double statistic=testable&&se>0?estimate/se:Double.NaN,pValue=Double.isFinite(statistic)?2*t.cumulativeProbability(-Math.abs(statistic)):Double.NaN;Double low=null,high=null;if(successful>=20&&successful>=.8*options.bootstrapReplicates()){final int index=j;double[] draws=replicates.stream().filter(Replicate::usable).mapToDouble(r->r.estimates[index]).sorted().toArray();low=quantile(draws,tail);high=quantile(draws,1-tail);}terms.add(new Term(parameter.name(),estimate,se,g-1,statistic,pValue,estimate-critical*se,estimate+critical*se,low,high));}
        List<String> warnings=new ArrayList<>();warnings.add("One-way CR0/CR1 inference clusters case scores; the point fit is a marginal Gaussian SEM, not a two-level decomposition. Clusters must be independent. Cluster t reference uses G−1 degrees of freedom and is an approximation, especially with few or highly unequal clusters.");warnings.add("Bootstrap resamples whole original clusters, including all their rows and missingness, with replacement. Failed attempts are counted without replacement. Percentile intervals require at least 20 usable and 80% of attempted replicates; this threshold is not a guarantee of accuracy.");if(g<30)warnings.add("Fewer than 30 informative clusters: cluster asymptotic inference may be unreliable.");if(rank<q)warnings.add("Cluster score covariance has rank "+rank+" of "+q+"; joint inference is singular. Individual SE may still be displayed but joint Wald tests are not supplied.");if(g<groups.size())warnings.add("Fully unobserved clusters contribute no score; informative-cluster count drives the correction and t reference.");if(!point.converged()||!point.locallyIdentified()||point.boundary())warnings.add("Point fit is nonregular; cluster Wald covariance is unavailable.");return new Fit(point,options,groups.size(),g,sizes,correction,covariance,rank,terms,replicates.size(),successful,replicates,warnings);
    }
    static double quantile(double[] sorted,double probability){double position=(sorted.length-1)*probability;int low=(int)Math.floor(position),high=(int)Math.ceil(position);return sorted[low]+(position-low)*(sorted[high]-sorted[low]);}
}
